function changeUrl(result,type){
var { java, cache } = this;
if(String(result).includes("/c/")){
 result = result.replace("/c/","/b/").split("/").slice(0,-1).join("/")+".html"
}
if(String(result).includes("/txt/")){
 result = result.replace("/txt/","/book/").split("/").slice(0,-1).join("/")+".htm"
}
if(String(result).includes("/book/") && !String(result).includes(".htm")){
 result = result.slice(0,-1)+".htm"
}
result =this.clearUrl(result)
return type==1?result:`data:;base64,${java.base64Encode(result)},{"type":"xsw8093"}`
}

